101	  });
102	
103	  return (
104	    <Shell
105	      nav={visibleNav}
106	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
107	      notifications={notifications.map((n) => ({
108	        id: n.id,
