70	function InviteForm({ orgId }: { orgId: string }) {
71	  const [email, setEmail] = useState("");
72	  const [role, setRole] = useState<string>("MEMBER");
73	  const [pending, start] = useTransition();
74	  const [msg, setMsg] = useState<{ tone: "error" | "info" | "ok"; text: string } | null>(null);
75	
76	  function submit(e: React.FormEvent) {
77	    e.preventDefault();
78	    setMsg(null);
79	    start(async () => {
80	      const res = await inviteMember(orgId, email, role);
81	      if (res.error) setMsg({ tone: "error", text: res.error });
82	      else if (res.ok) {
83	        setMsg({ tone: "ok", text: res.message ?? "Member added." });
84	        setEmail("");
85	      } else if (res.message) setMsg({ tone: "info", text: res.message });
86	    });
87	  }
