import { redirect } from "next/navigation";
import type { Membership, User } from "@prisma/client";
import { currentUser } from "./auth";
import { db } from "./db";

/**
 * Team area-based access — the customer-portal counterpart to lib/rbac.ts.
 *
 * An Organization's members each hold a Membership whose `role` is one of
 * OWNER / ADMIN / MEMBER / BILLING. OWNER and ADMIN implicitly reach every
 * dashboard area. For MEMBER / BILLING the optional `Membership.areas` field
 * (a JSON string[] of the area keys below) narrows what they may see and reach:
 *
 *   - `areas === null`  → no per-member restriction; the role's default (all
 *                         assignable areas) applies.
 *   - `areas === [...]` → the member may only reach the listed area keys.
 *
 * This is a plain module (NOT "use server") so both the pure helpers and the
 * `requireArea` page-guard can be imported anywhere — server components,
 * server actions, and client components (for the pure helpers).
 */

/** Canonical list of dashboard areas an owner/admin can assign to a member. */
export const DASHBOARD_AREAS = [
  { key: "servers", label: "Servers" },
  { key: "deploy", label: "Deploy" },
  { key: "games", label: "Game servers" },
  { key: "volumes", label: "Volumes" },
  { key: "domains", label: "Domains" },
  { key: "email", label: "Business email" },
  { key: "billing", label: "Billing" },
  { key: "invoices", label: "Invoices" },
  { key: "support", label: "Support" },
] as const;

export type AreaKey = (typeof DASHBOARD_AREAS)[number]["key"];

const AREA_KEYS = DASHBOARD_AREAS.map((a) => a.key) as readonly string[];

export function isAreaKey(v: string): v is AreaKey {
  return AREA_KEYS.includes(v);
}

/**
 * Sanitise an arbitrary input into a clean, de-duplicated list of valid area
 * keys. Used by `setMemberAreas` before persisting to `Membership.areas`.
 */
export function normalizeAreas(input: unknown): AreaKey[] {
  if (!Array.isArray(input)) return [];
  const seen = new Set<AreaKey>();
  for (const v of input) {
    if (typeof v === "string" && isAreaKey(v)) seen.add(v);
  }
  return [...seen];
}

/** Roles that reach every area regardless of `Membership.areas`. */
function isPrivilegedRole(role: string): boolean {
  return role === "OWNER" || role === "ADMIN";
}

/** A membership-shaped value: only `role` + `areas` are needed to decide access. */
type AreaMembership = { role: string; areas: unknown };

/**
 * Does this membership grant access to `areaKey`?
 *   - OWNER / ADMIN            → always true
 *   - MEMBER / BILLING, null   → true (role default = all areas)
 *   - MEMBER / BILLING, [...]  → true only if the list includes the key
 */
export function memberCanAccess(membership: AreaMembership, areaKey: string): boolean {
  if (isPrivilegedRole(membership.role)) return true;
  const { areas } = membership;
  if (areas === null || areas === undefined) return true;
  if (!Array.isArray(areas)) return false;
  return areas.includes(areaKey);
}

/**
 * Maps dashboard nav hrefs to their governing area key. Hrefs NOT listed here
 * (Dashboard home, Team, Settings, Refer, Affiliate, Feedback, Activity,
 * Build) are unrestricted — every member reaches them. The dashboard layout
 * uses this to hide nav items a constrained member can't reach.
 */
const HREF_AREA: Record<string, AreaKey> = {
  "/dashboard/servers": "servers",
  "/dashboard/deploy": "deploy",
  "/dashboard/games": "games",
  "/dashboard/volumes": "volumes",
  "/dashboard/domains": "domains",
  "/dashboard/email": "email",
  "/dashboard/billing": "billing",
  "/dashboard/invoices": "invoices",
  "/dashboard/support": "support",
};

/** The area governing an href, or null when the href is unrestricted. */
export function areaForHref(href: string): AreaKey | null {
  return HREF_AREA[href] ?? null;
}

/** Should this nav href be visible to a member with the given membership? */
export function memberCanAccessHref(membership: AreaMembership, href: string): boolean {
  const area = areaForHref(href);
  return area === null || memberCanAccess(membership, area);
}

/*
 * ---------------------------------------------------------------------------
 * ORCHESTRATOR NOTE — nav hiding in app/dashboard/layout.tsx
 * ---------------------------------------------------------------------------
 * The customer dashboard has no active-org switcher yet, so nav hiding only
 * applies once a member is "acting within" an organization (an org context the
 * orchestrator wires in). When that context exists, filter the nav the same way
 * the existing feature-flag pass does — around the `visibleNav` block in
 * app/dashboard/layout.tsx (currently lines ~87-95):
 *
 *   import { memberCanAccessHref } from "@/lib/team-areas";
 *   // `membership` = the acting member's Membership in the active org, or null
 *   const visibleNav = nav
 *     .map((section) => ({
 *       ...section,
 *       items: section.items.filter(
 *         (item) =>
 *           (!FEATURE_HREF[item.href] || flags[FEATURE_HREF[item.href]]) &&
 *           (!membership || memberCanAccessHref(membership, item.href)),
 *       ),
 *     }))
 *     .filter((section) => section.items.length > 0);
 *
 * Per-page enforcement uses `requireArea` below so a hand-typed URL is refused
 * too.
 */

/**
 * Server-side page guard for org-scoped dashboard pages. Given the active
 * organization and the area a page belongs to, it loads the current user's
 * membership and redirects home unless the member may reach the area. Returns
 * the membership so the page can reuse it.
 *
 * Mirrors lib/rbac.ts `requireArea`, but for org members rather than staff.
 */
export async function requireArea(orgId: string, area: AreaKey): Promise<Membership> {
  const user = await currentUser();
  if (!user) redirect("/login");
  const membership = await db.membership.findUnique({
    where: { orgId_userId: { orgId, userId: user.id } },
  });
  if (!membership) redirect("/dashboard");
  if (!memberCanAccess(membership, area)) redirect("/dashboard");
  return membership;
}

export type { User };

