import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { normalizeAreas } from "./team-areas";

/**
 * Set a member's allowed dashboard areas. Only OWNER/ADMIN act. The owner's
 * membership always keeps full access and can't be constrained here. Invalid
 * or unknown area keys are dropped; the resulting list is persisted verbatim to
 * `Membership.areas` (an empty list means "no restricted areas"). Passing every
 * area key is equivalent to full access.
 */
export async function setMemberAreas(
  membershipId: string,
  areas: string[],
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const target = await db.membership.findUnique({ where: { id: membershipId } });
  if (!target) return { error: "That membership no longer exists." };

  const actor = await actorMembership(target.orgId, user.id);
  if (!actor || !canAdminister(actor.role)) {
    return { error: "You don't have permission to change access in this organization." };
  }

  const org = await db.organization.findUnique({
    where: { id: target.orgId },
    select: { ownerId: true },
  });
  if (!org) return { error: "Organization not found." };
  if (target.role === "OWNER" || target.userId === org.ownerId) {
    return { error: "The organization owner always has full access." };
  }

  const clean = normalizeAreas(areas);
  await db.membership.update({
    where: { id: membershipId },
    data: { areas: clean },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "org.member_areas_changed",
      detail: `${target.userId} → [${clean.join(", ")}]`,
    },
