"use client";

import { useState, useTransition } from "react";
import { DASHBOARD_AREAS } from "@/lib/team-areas";
import { setMemberAreas } from "@/lib/actions-teams";

/**
 * Per-member dashboard-area editor. Renders one toggle per assignable area and
 * persists changes through the `setMemberAreas` server action. `initialAreas`
 * of null means the member currently has full (role-default) access, shown here
 * as every box checked; unchecking any box switches them to an explicit list.
 */
export default function MemberAreas({
  membershipId,
  initialAreas,
}: {
  membershipId: string;
  initialAreas: string[] | null;
}) {
  const [selected, setSelected] = useState<Set<string>>(
    () => new Set(initialAreas ?? DASHBOARD_AREAS.map((a) => a.key)),
  );
  const [restricted, setRestricted] = useState<boolean>(initialAreas !== null);
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ tone: "error" | "ok"; text: string } | null>(null);

  function persist(next: Set<string>) {
    setMsg(null);
    start(async () => {
      const res = await setMemberAreas(membershipId, [...next]);
      if (res.error) setMsg({ tone: "error", text: res.error });
      else {
        setRestricted(true);
        setMsg({ tone: "ok", text: "Access updated." });
      }
    });
  }

  function toggle(key: string, on: boolean) {
    const next = new Set(selected);
    if (on) next.add(key);
    else next.delete(key);
    setSelected(next);
    persist(next);
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <span className="text-xs font-medium text-slate-300">Dashboard access</span>
        {!restricted && (
          <span className="text-[11px] text-slate-500">full access (role default)</span>
        )}
      </div>
      <div className="flex flex-wrap gap-x-4 gap-y-1.5">
        {DASHBOARD_AREAS.map((a) => (
          <label
            key={a.key}
            className="flex items-center gap-1.5 text-xs text-slate-300"
          >
            <input
              type="checkbox"
              className="accent-brand-500"
              checked={selected.has(a.key)}
              disabled={pending}
              onChange={(e) => toggle(a.key, e.target.checked)}
            />
            {a.label}
          </label>
        ))}
      </div>
      {msg && (
        <span
          className={`text-[11px] ${msg.tone === "error" ? "text-red-400" : "text-emerald-400"}`}
        >
          {msg.text}
        </span>
      )}
    </div>
  );
}

